"use strict";

const http = require("http");
const https = require("https");
const zlib = require("zlib");
const { URL } = require("url");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const NAV_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "accept-encoding": "gzip, deflate, br",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u ? u.replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(setCookie) {
    const lines = Array.isArray(setCookie) ? setCookie : setCookie ? [setCookie] : [];
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function fetchTextOnce(urlStr, jar, headers, timeoutMs) {
  return new Promise((resolve, reject) => {
    let target;
    try {
      target = new URL(urlStr);
    } catch {
      reject(new Error(`Invalid URL: ${urlStr}`));
      return;
    }
    const lib = target.protocol === "http:" ? http : https;
    const req = lib.request(
      target,
      {
        method: "GET",
        headers: { ...NAV_HEADERS, cookie: jar.toString(), ...(headers || {}) },
      },
      (res) => {
        jar.absorb(res.headers["set-cookie"]);
        let stream = res;
        const enc = String(res.headers["content-encoding"] || "").toLowerCase();
        if (enc === "gzip") stream = res.pipe(zlib.createGunzip());
        else if (enc === "deflate") stream = res.pipe(zlib.createInflate());
        else if (enc === "br") stream = res.pipe(zlib.createBrotliDecompress());
        const chunks = [];
        stream.on("data", (c) => chunks.push(c));
        stream.on("end", () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            finalUrl: urlStr,
            text: Buffer.concat(chunks).toString("utf8"),
          })
        );
        stream.on("error", reject);
        res.on("error", reject);
      }
    );
    req.setTimeout(timeoutMs, () =>
      req.destroy(new Error(`Request timed out after ${timeoutMs}ms: ${urlStr}`))
    );
    req.on("error", reject);
    req.end();
  });
}

async function fetchText(url, jar, headers, timeoutMs = 25000, redirects = 5) {
  const res = await fetchTextOnce(url, jar, headers, timeoutMs);
  if (
    res.status >= 300 &&
    res.status < 400 &&
    res.headers.location &&
    redirects > 0
  ) {
    const next = new URL(res.headers.location, url).toString();
    return fetchText(next, jar, headers, timeoutMs, redirects - 1);
  }
  return res;
}

function parseJsonObjectAt(text, start) {
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) {
        try {
          return JSON.parse(text.slice(start, i + 1));
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

function extractPlayerConfig(html) {
  const marker = "window.playerConfig";
  const at = html.indexOf(marker);
  if (at < 0) return null;
  const open = html.indexOf("{", at);
  if (open < 0) return null;
  const cfg = parseJsonObjectAt(html, open);
  return cfg && cfg.video && cfg.request ? cfg : null;
}

async function fetchConfig(id, hash, jar) {
  const hq = hash ? `?h=${encodeURIComponent(hash)}` : "";
  let lastErr = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const page = await fetchText(
        `https://player.vimeo.com/video/${id}${hq}`,
        jar,
        { referer: "https://vimeo.com/" }
      );
      if (page.status === 200) {
        const cfg = extractPlayerConfig(page.text);
        if (cfg) return cfg;
      }
      lastErr = new Error(`Player page returned HTTP ${page.status}`);
    } catch (e) {
      lastErr = e;
    }
    try {
      const raw = await fetchText(
        `https://player.vimeo.com/video/${id}/config${hq}`,
        jar,
        { referer: "https://vimeo.com/", accept: "application/json, */*" }
      );
      if (raw.status === 200) {
        try {
          const cfg = JSON.parse(raw.text);
          if (cfg && cfg.video && cfg.request) return cfg;
        } catch {

        }
      }
      lastErr = new Error(`Player config returned HTTP ${raw.status}`);
    } catch (e) {
      lastErr = e;
    }
    await new Promise((r) => setTimeout(r, 700));
  }
  throw new Error(
    "Could not load this video's player config — it may be private, " +
      "embed-restricted, deleted, or Vimeo changed its player format" +
      (lastErr ? ` (last error: ${lastErr.message})` : "")
  );
}

function adaptiveUrl(files, kind) {
  const entry = files && files[kind];
  if (!entry || typeof entry !== "object") return null;
  const cdns = entry.cdns || {};
  const chosen = (entry.default_cdn && cdns[entry.default_cdn]) || Object.values(cdns)[0];
  if (!chosen) return null;
  return chosen.avc_url || chosen.url || null;
}

function parseVideoId(input) {
  const s = String(input || "").trim();
  let m = s.match(/player\.vimeo\.com\/video\/(\d{6,})(?:[?&]h=([A-Za-z0-9]+))?/);
  if (m) return { id: m[1], hash: m[2] || null };
  m = s.match(/vimeo\.com\/(?:channels\/[^/]+\/|groups\/[^/]+\/videos\/|album\/\d+\/video\/)?(\d{6,})(?:\/([A-Za-z0-9]{6,}))?(?:[?&]h=([A-Za-z0-9]+))?/);
  if (m) return { id: m[1], hash: m[3] || m[2] || null };
  if (/^\d{6,}$/.test(s)) return { id: s, hash: null };
  return { id: null, hash: null };
}

async function fetchSelf(url) {
  try {
    const { id, hash } = parseVideoId(url);
    if (!id) throw new Error("Invalid Vimeo URL");

    const jar = new Jar();
    const cfg = await fetchConfig(id, hash, jar);

    const v = cfg.video || {};
    const files = (cfg.request && cfg.request.files) || {};

    const progressive = (Array.isArray(files.progressive) ? files.progressive : [])
      .filter((r) => r && r.url)
      .sort((a, b) => (b.height || 0) - (a.height || 0) || (b.width || 0) - (a.width || 0));
    const best = progressive[0] || null;
    const hls = adaptiveUrl(files, "hls");

    let download;
    if (best) {
      download = {
        video: cleanUrl(best.url),
        type: "mp4",
        note: "Signed URL — download immediately, it expires soon",
      };
    } else if (hls) {
      download = {
        video: cleanUrl(hls),
        type: "hls",
        note: "Signed HLS master URL — download immediately, it expires soon",
      };
    } else {
      throw new Error("No download URL found in the player config (no progressive MP4 or HLS stream)");
    }
    if (!download.video) throw new Error("No download URL found in the player config");

    const thumbs = v.thumbs || {};
    return {
      success: true,
      source: "Vimeo",
      data: {
        title: v.title || "Vimeo Video",
        duration: typeof v.duration === "number" ? v.duration : null,
        thumbnail: cleanUrl(v.thumbnail_url || thumbs["1280"] || thumbs["640"] || null),
        download,
      },
    };
  } catch (e) {
    if (/^Vimeo Error:/.test(e.message)) throw e;
    throw new Error("Vimeo Error: " + e.message);
  }
}

module.exports = fetchSelf;
